BEGIN;

-- PREFLIGHT ASSERTIONS
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'stock_instruments') THEN RAISE EXCEPTION 'stock_instruments table missing'; END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'stock_instrument_venues') THEN RAISE EXCEPTION 'stock_instrument_venues table missing'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.stock_data_sources WHERE source_code = 'KRX_OPEN_API') THEN RAISE EXCEPTION 'KRX_OPEN_API source missing'; END IF;
END $$;


-- POST-DML ASSERTIONS
DO $$
DECLARE
  c INT;
BEGIN
  SELECT count(*) INTO c FROM public.stock_instruments WHERE stock_code IS NULL OR trim(stock_code) = '';
  IF c > 0 THEN RAISE EXCEPTION 'Post-DML Assertion failed: NULL or empty stock_code'; END IF;
  SELECT count(*) INTO c FROM public.stock_instruments WHERE listing_date IS NULL;
  IF c > 0 THEN RAISE EXCEPTION 'Post-DML Assertion failed: NULL listing_date'; END IF;
  SELECT count(*) INTO c FROM public.stock_instruments WHERE listing_status = 'DELISTED' AND (is_active = TRUE OR is_trade_eligible = TRUE);
  IF c > 0 THEN RAISE EXCEPTION 'Post-DML Assertion failed: DELISTED active or tradable'; END IF;
END $$;

COMMIT;

SELECT count(*) AS final_count FROM public.stock_instruments;
